from pathlib import Path
import json,html
r=Path(__file__).resolve().parent
runs=json.loads((r/'evidence/summary.json').read_text())
valid=[x for x in runs if not any(t in x['run'] for t in ['pilot','failed','ipad-opt-']) and x['exit']['reference'] and x['inputLatencyMs']['n']==24]
rows=[]
for x in valid:
 p=next(p for p in x['phases'] if p['name']=='scroll');l=x['inputLatencyMs'];s=x.get('staticRGB',{});rows.append('<tr>'+''.join(f'<td>{html.escape(str(v))}</td>' for v in [x['run'],f"{l['p50']:.1f} / {l['p95']:.1f}",f"{p['receivedDistinctFPS']:.1f}",f"{p['receivedMbps']:.2f}",f"{p['clientCPUPercentOneCore']:.1f}%",f"{s.get('meanAbsoluteChannelError',0):.3f}"] )+'</tr>')
options=''.join(f'<option value="{x["run"]}">{x["run"]}</option>' for x in valid)
metadata={x['run']:x for x in valid}
page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>WVE-79 browser-remoting measurements</title>
<style>body{font:15px/1.5 system-ui;margin:32px auto;max-width:1400px;padding:0 24px;color:#192333;background:#f7f9fc}h1{font-size:28px}h2{font-size:21px}table{border-collapse:collapse;background:white;width:100%;font-size:13px}th,td{padding:9px;text-align:left;border-bottom:1px solid #d4dce7}select,button{font:inherit;padding:8px}section{background:white;border:1px solid #d4dce7;border-radius:8px;padding:20px;margin:20px 0}.pictures{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}.pictures>div{min-width:0}.picture{overflow:auto;border:1px solid #ccd5e0;max-height:720px}img{display:block;max-width:none}label{margin-right:16px}.note{color:#526277;max-width:1050px}.bar{height:22px;background:#1769bc;border-radius:3px}.barrow{display:grid;grid-template-columns:330px 1fr 100px;align-items:center;gap:12px;margin:7px 0}.tools{display:flex;gap:10px;flex-wrap:wrap}pre{font-size:12px;white-space:pre-wrap}@media(max-width:800px){.pictures{grid-template-columns:1fr}.barrow{grid-template-columns:180px 1fr 60px}}</style>
<h1>Browser-remoting comparison</h1><p>WVE-79 · 13 September 2026 · Audio disabled</p><p class="note">Measured backend compositions on the existing Mac, Linux Host and connected iPad. These are bounded synthetic development-page tests, not general browser or production guarantees. Latency ends at decoded-pixel arrival, before physical display scanout. Each reported input run has 24 samples.</p>
<section><h2>Measured runs</h2><table><thead><tr><th>Run</th><th>Input p50 / p95 ms</th><th>Scrolling FPS</th><th>Scrolling Mb/s*</th><th>Client CPU**</th><th>Mean RGB error /255</th></tr></thead><tbody>ROWS</tbody></table><p class="note">* RFB: received TCP bytes. WebRTC: received RTP video payload bytes. Headers, signaling and retransmissions are not accounted identically. ** Percent of one CPU core, during scrolling; compare within a client device. Baseline WebRTC’s static-update delay is corrected in runs named “minfps”; final Mac WebRTC also uses that variant.</p></section>
<section><h2>Decoded text and pixel quality</h2><div class="tools"><label>Run <select id="run">OPTIONS</select></label><button id="fit">Fit CSS size</button><button id="one">1 image pixel per CSS pixel</button><button id="zoom">Zoom 2×</button></div><p class="note" id="geometry"></p><div class="pictures"><div><h3>Chromium reference</h3><div class="picture"><img id="reference"></div></div><div><h3>Native receiver pixels</h3><div class="picture"><img id="received"></div></div></div><p class="note">The reference is captured independently from the same browser after the page becomes static. Changing measurement-header pixels are excluded from the numeric comparison. This viewer displays decoded images; it does not establish the physical iPad panel’s color or text rendering.</p><pre id="detail"></pre></section>
<script>const data=DATA;let scale='fit';const select=document.getElementById('run');function show(){const x=data[select.value];for(const key of ['reference','received']){const img=document.getElementById(key);img.src='evidence/'+x.run+'/'+key+'.png';img.style.width=(scale==='fit'?960:scale==='one'?x.imageSize[0]:x.imageSize[0]*2)+'px'}document.getElementById('geometry').textContent=x.client+' · '+x.host+' Host · '+x.dpr+'× density · '+x.imageSize.join(' × ')+' pixels';document.getElementById('detail').textContent=JSON.stringify({inputLatencyMs:x.inputLatencyMs,staticRGB:x.staticRGB,referenceState:x.referenceState},null,2)}select.onchange=show;document.getElementById('fit').onclick=()=>{scale='fit';show()};document.getElementById('one').onclick=()=>{scale='one';show()};document.getElementById('zoom').onclick=()=>{scale='zoom';show()};show();</script>
'''
(r/'comparison.html').write_text(page.replace('ROWS',''.join(rows)).replace('OPTIONS',options).replace('DATA',json.dumps(metadata)))
print('Wrote comparison.html for',len(valid),'runs')
